import { setAgentContactPort } from "../../src/main/services/agent-contact.service";
import { getStats } from "../../src/main/services/dashboard.service";
import type { CenterContact } from "../../src/shared/online-crm";
import { strict as assert } from "node:assert";
import { initDatabase, runMigrations, getRawDb, getDb, closeDatabase } from "../../src/main/db";
import { searchGlobal, indexEmailBody } from "../../src/main/services/search.service";
import { setStage, listPipeline, getDetail, checkReminders } from "../../src/main/services/crm.service";
import { updateRuntimeConfig, loadConfig, saveConfig, DB_PATH } from "../../src/main/config";
import * as fs from "node:fs";
import { enrichMatchedMail } from "../../src/main/services/enrichment.service";
import { BASE_SCHEMA_SQL } from "../../src/main/db/schema-sql";
import * as Inbox from "../../src/main/services/inbox.service";
import { inboxMessages } from "../../src/main/db/schema/inbox";
import { eq } from "drizzle-orm";

async function run() {
  await initDatabase();
  getRawDb().exec(BASE_SCHEMA_SQL);
  getRawDb().exec(`INSERT INTO contacts(id,email,first_name) VALUES(10,'old@example.com','Antwerp');
    INSERT INTO interactions(id,contact_id,type,direction,body_preview) VALUES(10,10,'note','internal','Legacy Antwerp note');
    INSERT INTO email_accounts(id,email,encrypted_pass) VALUES(2,'oldmail@example.com','fixture');
    INSERT INTO inbox_messages(id,account_id,from_email,subject,body_preview,received_at) VALUES(10,2,'old@example.com','Legacy Antwerp','Antwerp preview','2026-01-01');`);
  runMigrations(); runMigrations();
  const db = getRawDb();
  assert.equal(db.prepare("SELECT count(*) AS n FROM _migrations WHERE name='v0.9-search-fts5'").get() && (db.prepare("SELECT count(*) AS n FROM _migrations WHERE name='v0.9-search-fts5'").get() as { n: number }).n, 1);
  db.exec(`INSERT INTO companies(id,name) VALUES(1,'Santos Logistics');
    INSERT INTO contacts(id,email,first_name,status,tags,extra) VALUES(1,'alice@santos.com','Santos','reached','["reaching"]','{"stageChangedAt":"2026-01-01T00:00:00Z"}');
    INSERT INTO interactions(id,contact_id,type,direction,body_preview,created_at) VALUES(1,1,'note','internal','Discuss Santos 运价','2026-01-01T00:00:00Z');
    INSERT INTO email_accounts(id,email,encrypted_pass) VALUES(1,'sales@example.com','fixture');
    INSERT INTO inbox_messages(id,account_id,from_email,subject,body_preview,classification,matched_contact_id,received_at) VALUES(1,1,'alice@santos.com','Santos freight','preview only','replied',1,'2026-01-02T00:00:00Z');`);
  const search = (query: string) => { const r = searchGlobal({ query }); assert.ok(r.success); return r.data; };
  assert.equal(search("Antwerp").email.length, 1); assert.equal(search("Antwerp").note.length, 1); assert.equal(search("Antwerp").contact.length, 1);
  assert.equal(search("Santos").email.length, 1); assert.equal(search("Santos").note.length, 1); assert.equal(search("Santos").contact.length, 1);
  assert.match(search("Santos").email[0]!.snippet, /\u0001Santos\u0002/i);
  assert.equal(search("运价").note.length, 1);
  assert.ok(indexEmailBody(1, "Full body Rotterdam 上海报价").success);
  assert.equal(search("Rotterdam").email.length, 1); assert.equal(search("上海报价").email.length, 1);
  db.exec("UPDATE inbox_messages SET matched_contact_id=1,subject='New subject' WHERE id=1");
  assert.equal(search("Rotterdam").email.length, 1); // 改标签/主题不丢完整正文
  db.exec("UPDATE interactions SET body_preview='Hamburg note' WHERE id=1");
  assert.equal(search("Hamburg").note.length, 1); assert.equal(search("Santos").note.length, 0);
  const centerRow = { contactId: 99, customerId: 'center-customer', email: 'center@example.invalid', firstName: 'CenterOnly', lastName: null, companyName: 'Center Ltd', tags: [], extra: {}, touchStatus: 'contacted', relationshipStage: 'quoting', lastFollowupNote: 'Center followup needle' } as unknown as CenterContact;
  const centerPort = { snapshot: () => ({ ok: true as const, data: { scope: 'fixture', active: () => true, contacts: [centerRow] } }) };
  setAgentContactPort(centerPort as never);
  const centerStats = getStats(); assert.ok(centerStats.success);
  assert.equal(centerStats.data.totalContacts, 1, 'dashboard must count authorized center rows, not old SQLite rows');
  assert.equal(centerStats.data.pipelineSummary.quoting, 1);
  assert.equal(search('CenterOnly').contact.length, 1, 'center contacts must be searchable');
  assert.equal(search('Santos').contact.length, 0, 'must not leak legacy contacts into center search');
  assert.equal(search('followup needle').note.length, 1);
  assert.equal(search('CenterOnly').contact[0]!.customerId, 'center-customer');
  setAgentContactPort({ snapshot: () => ({ ok: false, error: { code: 'UNAVAILABLE', message: '同步中' } }) } as never);
  assert.equal(getStats().success, false); assert.equal(searchGlobal({query:'Santos'}).success, false);
  setAgentContactPort(null);
  const before = listPipeline(); assert.ok(before.success); const beforeContact = before.data.flatMap(s => s.contacts)[0]!;
  assert.ok((await setStage(1, "quoting")).success);
  const after = listPipeline(); const detail = getDetail(1); assert.ok(after.success); assert.ok(detail.success);
  assert.equal(after.data.flatMap(s => s.contacts)[0]!.lastFollowupAt, beforeContact.lastFollowupAt);
  assert.ok(detail.data.timeline.some(e => e.type === "stage"));
  const sixDaysAgo = new Date(Date.now() - 6 * 86_400_000).toISOString();
  db.prepare("UPDATE inbox_messages SET received_at=? WHERE id=1").run(sixDaysAgo);
  db.prepare("UPDATE interactions SET created_at=? WHERE id=1").run(sixDaysAgo);
  assert.ok(updateRuntimeConfig({ crm: { silentOverdueDays: 7 } }).success);
  assert.equal(loadConfig().crm.todoAdvanceDays, 2);
  const seven = listPipeline(); const sevenReminders = checkReminders(); const sevenDetail = getDetail(1);
  assert.ok(seven.success && sevenReminders.success && sevenDetail.success);
  assert.equal(seven.data.flatMap(s => s.contacts)[0]!.overdue, false);
  assert.equal(seven.data.flatMap(s => s.contacts)[0]!.overdueDays, 7);
  assert.equal(sevenDetail.data.contact?.overdue, false); assert.equal(sevenReminders.data.overdue.length, 0);
  assert.ok(updateRuntimeConfig({ crm: { silentOverdueDays: 5 } }).success);
  const five = checkReminders(); assert.ok(five.success); assert.equal(five.data.overdue.length, 1);
  assert.equal(updateRuntimeConfig({ crm: { silentOverdueDays: 0 } }).success, false);
  assert.equal(updateRuntimeConfig({ crm: { warnDays: 9 } }).success, false);
  saveConfig({ ...loadConfig(), crm: { ...loadConfig().crm, silentOverdueDays: 0, warnDays: NaN } });
  assert.equal(loadConfig().crm.silentOverdueDays, 5); assert.equal(loadConfig().crm.warnDays, 3);
  assert.ok(enrichMatchedMail(1, "Regards\nSales Manager\nCompany: Santos Logistics\nTel: +55 11 1234 5678").success);
  assert.equal((db.prepare("SELECT title FROM contacts WHERE id=1").get() as { title: string }).title, "Sales Manager");
  db.exec("UPDATE contacts SET first_name='Hamburg',email='alice@example.com' WHERE id=1");
  assert.equal(search("Hamburg").contact.length, 1);
  db.exec("DELETE FROM interactions WHERE contact_id=1; DELETE FROM inbox_messages WHERE id=1; DELETE FROM contacts WHERE id=1");
  assert.equal(search("Hamburg").note.length, 0); assert.equal(search("Rotterdam").email.length, 0); assert.equal(search("Hamburg").contact.length, 0);
  assert.ok(indexEmailBody(1, "Rotterdam").success); assert.equal(search("Rotterdam").email.length, 0);
  for (const q of ['" OR *', "' UNION SELECT 1 --", "NEAR(", "%_", "<script>"]) assert.ok(searchGlobal({ query: q }).success);
  assert.equal(searchGlobal({ query: "Santos", limit: 0 }).success, false);
  // 真服务编排 + 假协议适配器：抓取响应不等待正文，id=0 的协议返回仍可后台回填。
  db.exec("UPDATE email_accounts SET imap_host='imap.fixture.invalid' WHERE id=1; INSERT INTO contacts(id,email) VALUES(2,'bob@example.com')");
  let releaseBody!: () => void;
  const bodyGate = new Promise<void>(resolve => { releaseBody = resolve; });
  Inbox.setImapFetchBodyFn(async () => {
    await bodyGate;
    const html = "<p>Rotterdam quotation</p><p>Regards</p><p>Operations Manager</p><p>Tel: +55 11 9999 8888</p>";
    await Inbox.writeBodyFile(2, html);
    return { success: true, data: html };
  });
  Inbox.setImapFetchFn(async () => {
    db.exec("INSERT INTO inbox_messages(id,account_id,message_id,from_email,classification,matched_contact_id,received_at) VALUES(2,1,'fixture-new-mail','bob@example.com','replied',2,'2026-10-09')");
    const row = getDb().select().from(inboxMessages).where(eq(inboxMessages.id, 2)).get()!;
    return { success: true, data: [{ ...row, id: 0 }] };
  });
  assert.ok((await Inbox.refreshInbox(1)).success);
  assert.equal((db.prepare("SELECT title FROM contacts WHERE id=2").get() as { title: string | null }).title, null);
  releaseBody();
  await Inbox.prefetchRecentBodies();
  await new Promise<void>(resolve => setImmediate(resolve));
  assert.equal((db.prepare("SELECT title FROM contacts WHERE id=2").get() as { title: string }).title, "Operations Manager");
  assert.equal(search("Rotterdam").email.length, 1);
  // 全局搜索可命中超出常规分类上限的邮件：只附带目标，不取消列表上限。
  const historicalId = 9000;
  const overLimitMailCount = 501;
  const missingMailId = 999999;
  db.prepare("INSERT INTO inbox_messages(id,account_id,from_email,classification,received_at) VALUES(?,1,'history@example.test','other','1990-01-01')").run(historicalId);
  const insertMail = db.prepare("INSERT INTO inbox_messages(account_id,from_email,classification,received_at) VALUES(1,'recent@example.test','other','2026-10-10')");
  db.transaction(() => { for (let i = 0; i < overLimitMailCount; i++) insertMail.run(); })();
  const normalList = Inbox.listInbox(); assert.ok(normalList.success);
  assert.ok(!normalList.data.some(r => r.id === historicalId));
  const linkedList = Inbox.listInbox({ includeId: historicalId }); assert.ok(linkedList.success);
  assert.equal(linkedList.data.filter(r => r.id === historicalId).length, 1);
  assert.equal(linkedList.data.length, normalList.data.length + 1);
  assert.equal(Inbox.listInbox({ includeId: -1 }).success, false);
  const deletedList = Inbox.listInbox({ includeId: missingMailId }); assert.ok(deletedList.success);
  assert.equal(deletedList.data.length, normalList.data.length);
  const indexes = db.prepare("SELECT name FROM sqlite_master WHERE type='index'").all() as { name: string }[];
  assert.ok(indexes.some(i => i.name === "idx_interactions_contact_id")); assert.ok(indexes.some(i => i.name === "idx_inbox_matched"));
  db.exec(fs.readFileSync(process.env.BACKEND_ROLLBACK_SQL!, "utf8"));
  closeDatabase();
  // 回退后模拟旧版连接（不注册 search_latin），业务表仍可写入。
  const BetterSqlite3 = require("better-sqlite3");
  const oldConnection = new BetterSqlite3(DB_PATH);
  oldConnection.exec("UPDATE contacts SET first_name='After rollback' WHERE id=2");
  assert.equal(oldConnection.prepare("SELECT first_name FROM contacts WHERE id=2").get().first_name, "After rollback");
  oldConnection.close();
  process.stdout.write("BACKEND_RUNTIME_OK\n");
}
run().catch(error => { process.stderr.write(error.stack || String(error)); closeDatabase(); process.exitCode = 1; });
